# Own-wording items of Dark Matter (2024), chunk B: Embedded Mini Fridge up to Nanobot Canister (Reconstructive). Row shape as tghp_item.py.
# Grafts are Wondrous Item rows (slot and price in the text). Plain gear and ship systems are GEAR rows: name, cost gp, weight lb, type, text.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

# ---- Construct Grafts
add("Embedded Mini Fridge", "Wondrous Item", "Common", 0, "Graft (Internal slot, 75 gp). A chilled compartment in your abdomen holds up to six cans of Krash, potions, or similar drinks.")
add("Embedded Translator", "Wondrous Item", "Uncommon", 0, "Graft (Head slot, 150 gp). A Universal Translator is built into your skull. You can use it at will.")
add("Embedded Weapon", "Wondrous Item", "Uncommon", 0, "Graft (Arms slot, base weapon price plus 200 gp). Choose a Simple or Martial weapon. It is built into one or both arms. When you draw it, the hand or hands become the weapon and cannot be disarmed of it. A transformed hand cannot hold or use any other weapon, Shield, or object.")
add("Embedded Weapon +1", "Wondrous Item", "Rare", 0, "Graft (Arms slot, base weapon price plus 750 gp). As Embedded Weapon, with a +1 bonus to attack and damage rolls made with it.", fx={"atk": 1, "dmg": 1})
add("Embedded Weapon +2", "Wondrous Item", "Very Rare", 0, "Graft (Arms slot, base weapon price plus 5,700 gp). As Embedded Weapon, with a +2 bonus to attack and damage rolls made with it.", fx={"atk": 2, "dmg": 2})
add("Embedded Weapon +3", "Wondrous Item", "Legendary", 0, "Graft (Arms slot, base weapon price plus 55,200 gp). As Embedded Weapon, with a +3 bonus to attack and damage rolls made with it.", fx={"atk": 3, "dmg": 3})
add("Final Word", "Wondrous Item", "Very Rare", 0, "Graft (Internal slot, 100,000 gp). A tiny Arcane Warhead inside you is wired to your life. When you die, it detonates and destroys your body, so only True Resurrection or Wish can restore you. Each creature in a 180-ft-radius Sphere centered on you makes a DC 19 Dexterity save. Creatures within 60 ft cannot avoid the damage with Evasion or similar features. A failed save takes 1d4 Mega (1d4 x 100) Force damage, a success takes half.")
add("Finger Picks", "Wondrous Item", "Uncommon", 0, "Graft (Arms slot, 800 gp). A mechanical hand holds a retractable set of Thieves' Tools in its fingers. Extend or retract them as a Bonus Action. Retracted, they are perfectly hidden. You have proficiency with Thieves' Tools. If you already had it, double your Proficiency Bonus on checks that use them.")
add("Golem Arms", "Wondrous Item", "Rare", 0, "Graft (Arms slot, 6,000 gp). Arms taken from a golem or similar Construct. Your reach is 5 ft greater on Melee weapon attacks and Unarmed Strikes. You have Advantage on Strength checks and saving throws.")
add("Hacker Hands", "Wondrous Item", "Common", 0, "Graft (Arms slot, 150 gp). Fingers that plug into machines and split into smaller digits for fast typing. The graft counts as an Interface Rig. When you fail a hacking attempt, reroll it and keep the new result. You cannot do this again until you finish a Long Rest.")
add("Heart of Steel", "Wondrous Item", "Common", 0, "Graft (Internal slot, 350 gp). An automaton's core replaces your heart. You do not need to sleep, and magic cannot put you to sleep. You can finish a Long Rest in 4 hours if you spend them motionless but conscious.")
add("Heavy Legs", "Wondrous Item", "Uncommon", 0, "Graft (Legs slot, 500 gp). A mechanical exoskeleton is rooted in your legs. As a Bonus Action, kick a Large or smaller creature within 5 ft with an Unarmed Strike. On a hit, it is pushed 5 ft away from you. You count as one size larger for carrying capacity.")
add("Impulse Unit", "Wondrous Item", "Uncommon", 0, "Graft (Legs slot, 750 gp). Thrusters in your legs and back. Once per turn, after you move at least 15 ft in a straight line, you can move up to 10 ft more in that direction without spending movement. Or spend 10 ft of movement to jump 10 ft vertically.")
add("Infrasight Eyes", "Wondrous Item", "Uncommon", 0, "Graft (Head slot, 200 gp). Sensor eyes that see in the dark. You have Darkvision with a range of 60 ft.", fx={"dark": 60})
add("Laser Eyes", "Wondrous Item", "Uncommon", 0, "Graft (Head slot, 250 gp). One or both eyes are laser emitters. Ranged weapon, 2d4 Radiant, range 50/200 ft, Vex mastery, Blaster and Firearm properties. You are proficient with it and cannot be disarmed of it. You cannot use it while Blinded.")
WPN["Laser Eyes"] = {"d": "2d4", "t": "Radiant", "cat": "S", "k": "R", "p": "Blaster, Firearm", "m": "Vex", "w": 0, "r": "50/200", "xw": 1}
add("Lazarus Unit", "Wondrous Item", "Rare", 0, "Graft (Internal slot, 6,000 gp). A defibrillator or similar device in your vital organs. If you are dead or at 0 Hit Points at the start of your turn, it shocks you back with 1 Hit Point. It fails if you have no heart, died of old age, or lack vital organs. After it works, it cannot work again until you finish a Long Rest.", ch=[1, "1", "long"])
add("Logic Unit", "Wondrous Item", "Common", 0, "Graft (Head slot, 150 gp). A processing unit boosts your brain. Add half your Proficiency Bonus (round down) to Intelligence checks that use a skill you lack proficiency in, if your Proficiency Bonus is not already included. You know Machine Code, the language of machines, and the Technomancy cantrip. Choose Intelligence, Wisdom or Charisma as its spellcasting ability when you install it.")

# ---- Magic items
add("Encyclopedia Multiplanaria", "Wondrous Item", "Legendary", 0, "A Datapad holding a vast but unindexed store of knowledge. It offers only what it judges useful at the moment. It has 3 charges and regains all of them at dawn. When you take the Study action, spend 1 charge to gain +20 on Intelligence checks you make as part of that action.", ch=[3, "all", "dawn"])
add("Etheradio", "Wondrous Item", "Rare", 0, "A 1,000 lb radio standing over 6 ft tall, plus a 3 ft antenna, that sends and receives audio through the Ethereal Plane. **Transmitting.** Utilize action: send up to 10 minutes of audio to a specific Etheradio on the same plane, or to a station. A message to all Etheradios on the plane via an emergency station can be sent once per day. Any message takes 10 minutes to arrive. **Receiving.** It stores the last 10 hours of audio it received. Utilize action: play it back or tune to a station. **Calibration.** It works only when calibrated to its location. This takes 1 hour and must be redone after moving it over 100 miles.")
add("Exo-Frame", "Armor", "Rare", 1, "A mechanized, bipedal frame weighing over 2,000 lb. You need no armor training, and you don and doff it as a Utilize action. **Armor Class.** Your AC is 18 and Dexterity does not affect it. You can still use a Shield. **Size.** You become Large if smaller. **Mighty.** Advantage on Strength checks and saving throws. **Integrated Battlefists.** It holds two Battlefists, and you are proficient with them. **Life Suit.** It gives the benefits of a Life Suit.")
add("Finger Gun Glove", "Wondrous Item", "Uncommon", 1, "Requires attunement by a spellcaster. A fingerless glove that lets you cast the Finger Guns cantrip with your spellcasting ability. You can use its mastery property while attuned.")
add("Flamethrower", "Wondrous Item", "Uncommon", 0, "A two-handed nozzle wired to a backpack of arcane batteries. It has 7 charges and regains 1d6 + 1 at dawn. When you take the Attack action, replace one or more attacks with a 15-ft Cone of fire, spending 1 charge per attack replaced. Dexterity save DC 13, 3d6 Fire on a fail, half on a success. **Upgraded.** With Martial weapon proficiency, the DC rises to 15 at level 5, 17 at level 11, and 18 at level 17.", ch=[7, "1d6+1", "dawn"])
add("Flashback Polaroid", "Wondrous Item", "Rare", 0, "An antique camera loaded with 1d6 + 2 blank photos. Magic action: take a picture to cast Flashback. The developed photo shows the events the spell changed. When the last photo is taken, the camera stops being magical.")
add("Flashbang", "Wondrous Item", "Uncommon", 0, "Utilize action: throw it up to 30 ft. A moment after impact it bursts in a 10-ft-radius Sphere. Each creature there makes a DC 13 Constitution save or is Blinded and Deafened until the start of your next turn. A creature that shields its eyes and ears succeeds automatically. Cost 125 gp.")
add("Freeze Bomb", "Wondrous Item", "Uncommon", 0, "Utilize action: throw it up to 30 ft. A moment after impact it bursts in a 10-ft-radius Sphere. Each creature there makes a DC 13 Constitution save. A fail takes 3d8 Cold damage, has Speed 0, and has Disadvantage on attack rolls until the start of your next turn. A success takes half damage only.")
add("Gamestation", "Wondrous Item", "Common", 0, "A small Datapad full of games. If you spend a Short Rest playing on it, you have Advantage on the next ability check you make before you finish a Short or Long Rest.")
add("Gamma Fragment", "Wondrous Item", "Uncommon", 1, "A crystal shard of pure hardlight with 6 charges. It regains 1d6 charges at dawn. When you make a D20 Test, spend charges up to your Proficiency Bonus and add that number to the d20 roll, to a maximum of 20. If you boost an attack roll that deals damage, you can change its damage type to Force. **Set.** Attuning to several Gamma Fragments counts as one attunement. Their charges form one pool that regains 1d6 per fragment at dawn.", ch=[6, "1d6", "dawn"])
add("Gamma Pendant", "Wondrous Item", "Artifact", 1, "A mithral medallion set with glowing green crystal, once shattered, its Gamma Fragments scattered across the 'Verse. It has 10 charges and regains 1d6 + 4 at dawn. **Incomplete.** You have a Fly Speed equal to your Speed. You breathe underwater and in vacuum and ignore extreme heat, cold and pressure. You can cast Lesser Spells from it (save DC 18) at these charge costs: Hardlight Blaster 2, Hardlight Chains 3, Hardlight Construction 5, Hardlight Gauntlet 5, Hardlight Traps 3. **Complete.** With 3 or more Gamma Fragments unified with it, it gains the benefits of all of them, 20 charges, and regains 1d10 + 10 at dawn. You can also cast Greater Spells: Hardlight Frame 7, Orbital Hardlight Cannon 13, Wall of Force 7. Any weapon you wield gets +2 to attack and damage (or its higher bonus) and can deal Force damage or its normal type. You have Advantage on saves against spells. As a Reaction when a creature you see within 60 ft casts a spell, absorb it. The spell has no effect, its casting time is wasted, and the pendant regains charges equal to the spell's level, up to 20. This works once per dawn. **Destruction.** It is impervious to damage, but two hardlight constructs the size of a small planet could crush it.", ch=[10, "1d6+4", "dawn"])
add("Grasshopper", "Weapon", "Rare", 0, "Dueling Laser. On a hit it deals an extra 2d10 Radiant damage and the target is pushed 10 ft away from you. After you attack with it, it Overheats and cannot attack again until the end of your next turn.", base=["Dueling Laser"], xd=["Hit: +2d10 Radiant and push 10 ft"])
add("Gravity Gun", "Wondrous Item", "Uncommon", 1, "It has 7 charges and regains 1d6 + 1 at dawn. Holding it, use a Magic action and 1 charge to cast Levitate (DC 13). Instead of rising, the target is pulled toward the device and hovers in a space you choose within 5 ft of you. As a Bonus Action, you can hurl a levitating target within 5 ft up to 60 ft in a direction you choose, which ends the spell. If it hits an obstacle, both take 4d6 damage, and the GM picks Bludgeoning, Piercing or Slashing. In Zero Gravity, all creatures and objects count as levitating. **Upgraded.** With Martial weapon proficiency, the DC rises to 15 at level 5, 17 at level 11, and 18 at level 17.", ch=[7, "1d6+1", "dawn"])
SP["Gravity Gun"] = {"sp": [["Levitate", 1]], "dc": 13}
add("Gravity Nullifier", "Wondrous Item", "Common", 0, "Magic action: attach this fist-sized device to an object under 2,000 lb. Its mass is nullified as if Levitate targeted it. It works for 10 minutes, then burns out for good. An object still aloft drifts gently to the ground. Cost 50 gp.")
add("Greater Shipmending Spray", "Wondrous Item", "Uncommon", 0, "A 20 lb canister of pressurized nanites. Use it as a Magic action from inside or outside a damaged ship. The ship regains 6d6 Mega Hit Points.")
add("Hardlight Bracer", "Wondrous Item", "Uncommon", 1, "It has 20 charges and regains 1d10 + 5 at dawn. Magic action, 1 charge: make a Hardlight Dart appear in your open hand. If unused, it fades after 24 hours.", ch=[20, "1d10+5", "dawn"])
add("Heretical Sunstaff of Ra", "Weapon", "Uncommon", 1, "Avia-Ra Sunstaff. When it deals the Bludgeoning damage of its Bludgeon mastery, it adds 1d6 Radiant. **Upgraded.** You gain +1 to attack and damage with it at level 5, +2 at level 11, and +3 at level 17. **Set.** Attuning to this sunstaff, an Ankh of Ra and Solar Wings of Ra counts as one attunement. With the sunstaff and one other of these, use a Magic action to loose a 5-ft-wide, 60-ft-long Line of light. Each creature in it makes a DC 15 Constitution save or is Blinded until the end of your next turn. This works once per dawn.", base=["Avia-Ra Sunstaff"], xd=["Bludgeon mastery: +1d6 Radiant"])
add("Holo-Companion", "Wondrous Item", "Uncommon", 0, "Press the button on this faceted orb as a Magic action to project a translucent humanoid figure around it. The figure works exactly like Unseen Servant, but is visible. Its creator decides its look.")
add("Holo-Sphere", "Wondrous Item", "Common", 0, "Magic action: set this 6-inch Sphere within 15 ft of you. It records holograms of events in a 15-ft Emanation around it, up to 5 minutes in total. As a Magic action, pause recording, delete a scene, or play one back at full size or at 1-ft scale. Magic interferes with recording, and heavy magic can turn playback into a garbled mess. Cost 75 gp.")
add("Hoverboard", "Wondrous Item", "Rare", 0, "A 3-ft metal board that hovers over any surface. Mount or dismount as a Bonus Action. While riding it, your Speed rises by 10 ft, you ignore Difficult Terrain, and you can cross liquids without sinking. It cannot climb inclines steeper than 45 degrees outside zero gravity. Use a Dexterity (Acrobatics) or Charisma (Performance) check for tricks.")
add("Hyper-Krash", "Potion", "Rare", 0, "A discontinued, too-extreme energy drink. When you drink it, you gain an extra action this turn, usable only for the Attack (one attack), Dash, Disengage, Hide or Utilize action. You also have Advantage on attack rolls and ability checks until the end of the turn. Then lethargy sets in, and you cannot gain its benefits again for 1 hour.")
add("Invisibomb", "Wondrous Item", "Uncommon", 0, "Utilize action: throw it up to 30 ft. On impact it bursts in a shimmering 30-ft-radius Sphere. Each creature and each object not worn or carried there is Invisible until the start of your next turn. The condition ends early for a creature once it makes an attack roll, deals damage, or casts a spell.")
add("Jax", "Potion", "Rare", 0, "Inject it as a Bonus Action. For 1 hour, your Strength and Dexterity each rise by 2, to a maximum of 22. Succeed on a DC 10 Constitution save or have a bad reaction, dropping to 0 Hit Points, falling unconscious, and being unable to regain Hit Points for 1 hour. You can inject up to three doses in the same Bonus Action. Each extra dose raises both scores by a further 2, to a maximum of 26, and adds 5 to the save DC, to a maximum of 25.")
add("Jetpack", "Wondrous Item", "Uncommon", 0, "A small impulse engine on straps with a handheld controller. It has 4 charges and regains 1d4 at dawn. Wear it on your back, then use a Magic action and 1 charge to gain a Fly Speed equal to your Speed for 10 minutes.", ch=[4, "1d4", "dawn"], fx={"fly": "walk"})
add("Justiciar's Gavel", "Weapon", "Uncommon", 1, "Rocket Hammer, the badge of office of a dwarven justicar. Once per turn, when you hit with a melee attack using it, fire its thrusters for an extra 1d4 Bludgeoning damage, or 1d6 if the target is Bloodied. **Upgraded.** You gain +1 to attack and damage with it at level 5, +2 at level 11, and +3 at level 17.", base=["Rocket Hammer"], xd=["Once per turn: +1d4 Bludgeoning (1d6 if Bloodied)"])
add("Life Suit", "Wondrous Item", "Common", 0, "A one-piece jumpsuit with a domed glass helmet. You breathe underwater and in vacuum for up to 24 hours at a time. It protects against extreme temperatures and pressures, inhaled poisons and gases, and contagions. You can wear it under armor. To refill its air, take it off for 2 hours. Cost 100 gp.")
add("Motion Tracker", "Wondrous Item", "Uncommon", 0, "A scanner with an illuminated screen. Holding it, you learn the location of every creature or object within 60 ft that has moved since the end of your last turn, even if Invisible or behind Cover. A creature Invisible from the Hide action avoids detection.")
add("Nanobot Canister (Deconstructive)", "Wondrous Item", "Rare", 0, "A capsule of short-lived nanobots. All three kinds look the same, and a DC 15 Intelligence (Technology) check tells which one it holds. Magic action: throw it at a creature, object or empty space within 30 ft. At an empty space, the nanobots cover a 5-ft square. **Deconstructive.** The target makes a DC 15 Dexterity save or is covered. At the start of each of its turns, it takes 1d10 Necrotic damage that ignores Resistance and Immunity. After 1 minute the nanobots shut down for good.")
add("Nanobot Canister (Reconstructive)", "Wondrous Item", "Rare", 0, "A capsule of short-lived nanobots. All three kinds look the same, and a DC 15 Intelligence (Technology) check tells which one it holds. Magic action: throw it at a creature, object or empty space within 30 ft. At an empty space, the nanobots cover a 5-ft square. **Reconstructive.** The target is covered and regains 1d6 Hit Points at the start of each of its turns. After 1 minute the nanobots shut down for good.")

