add("Ghost Suit", "Armor", "Rare", 1, "Any Light armor can be made as a Ghost Suit. The color shifts to match the surroundings. If you moved 15 ft or less on your turn, you have Advantage on Dexterity (Stealth) checks made for the Hide action. You can also Hide while Lightly Obscured.", base=["Padded Armor", "Leather Armor", "Studded Leather Armor"])
add("Golem Skin", "Armor", "Rare", 1, "Any armor can be made as Golem Skin. Glowing attachment points trace its surface. It has four body slots for construct grafts: Arms, External, Head and Legs. While you wear it, you gain the benefits of grafts installed in it and lose those of grafts on your own body, except Internal ones. You can don and doff it as a Bonus Action.")
add("Hullcutter", "Weapon", "Uncommon", 0, "A Plasma Cutter or Thermal Lance with a +1 bonus to attack and damage rolls. When it hits a ship or a Mega creature, it deals 1 Mega Hit Point of damage.", fx={"atk": 1, "dmg": 1}, base=["Plasma Cutter", "Thermal Lance"])

